import pandas as pd

def loan_types(loans: pd.DataFrame) -> pd.DataFrame:
    grouped = loans.groupby('user_id')['loan_type'].agg(set).reset_index()
    res = grouped[grouped['loan_type'].apply(lambda s: {'Refinance', 'Mortgage'}.issubset(s))]
    return res[['user_id']].sort_values(by='user_id')
